package com.bank.grpc;

import com.amazonaws.services.lambda.runtime.Context;
import com.amazonaws.services.lambda.runtime.RequestHandler;
import com.bank.grpc.gen.*;
import io.grpc.ManagedChannel;
import io.grpc.ManagedChannelBuilder;
import io.grpc.StatusRuntimeException;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import java.util.logging.Logger;

public class BalanceLambda implements RequestHandler<Map<String, String>, String> {
    private static final Logger log = Logger.getLogger(BalanceLambda.class.getName());

    // STATIC channel built in init phase → reused across WARM invocations.
    // On COLD start this is rebuilt and pays full HTTP/2 + TLS setup cost.
    private static final ManagedChannel CHANNEL = ManagedChannelBuilder
        .forTarget(System.getenv().getOrDefault("GRPC_TARGET", "localhost:9090"))
        .usePlaintext()          // use TLS in real deployments
        .keepAliveTime(30, TimeUnit.SECONDS)
        .build();

    private static final AccountServiceGrpc.AccountServiceBlockingStub STUB =
        AccountServiceGrpc.newBlockingStub(CHANNEL);

    @Override
    public String handleRequest(Map<String, String> event, Context ctx) {
        String accountId = event.getOrDefault("accountId", "SAV2001"); // Rajesh
        try {
            // UNARY only — streaming is impractical in a short-lived function.
            // Tight deadline so a hung call never burns the whole Lambda timeout.
            BalanceResponse resp = STUB
                .withDeadlineAfter(2, TimeUnit.SECONDS)
                .getBalance(BalanceRequest.newBuilder().setAccountId(accountId).build());
            log.info(() -> "Balance " + accountId + " = Rs." + resp.getBalance());
            return "{\"accountId\":\"" + accountId + "\",\"balance\":\"" + resp.getBalance() + "\"}";
        } catch (StatusRuntimeException e) {
            log.severe("gRPC call failed: " + e.getStatus().getCode());
            return "{\"error\":\"" + e.getStatus().getCode() + "\"}";
        }
        // NOTE: API Gateway (REST/HTTP) does NOT proxy native gRPC to Lambda.
        // Browser clients → gRPC-Web + Envoy; native gRPC → ALB → containers.
    }
}
